#Requires -Version 7
<#
.SYNOPSIS
    Scripted smell detection: semgrep (regex + AST rules), jscpd (clones), and the
    detectors/scripts/*.py scripts. Dot-source this file.
.DESCRIPTION
    Output is deterministic: hits sorted by smell, file, line, ids assigned after
    sorting. A tool that cannot run marks its smells 'not assessed' -- never zero --
    except semgrep, whose absence stops the run: every regex smell depends on it.
#>
$ErrorActionPreference = 'Stop'

$script:ExcludeDirs = @('bin', 'obj', 'node_modules', 'dist')
$script:ExcludeGlobs = @('package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', 'packages.lock.json', '*.min.js', '*.min.css')
$script:GeneratedGlobs = @('*.g.cs', '*.g.i.cs', '*.designer.cs', '*.generated.cs', '*.generated.ts', '*.generated.tsx', '*.generated.js', '*.generated.jsx')
$script:LanguageByExtension = @{
    '.cs' = 'csharp'; '.ts' = 'typescript'; '.tsx' = 'typescript'; '.js' = 'javascript'; '.jsx' = 'javascript'
    '.mjs' = 'javascript'; '.cjs' = 'javascript'; '.py' = 'python'; '.go' = 'go'; '.java' = 'java'
    '.rs' = 'rust'; '.rb' = 'ruby'; '.kt' = 'kotlin'; '.swift' = 'swift'; '.cpp' = 'cpp'; '.c' = 'c'; '.ps1' = 'powershell'; '.psm1' = 'powershell'
}

function Split-ByLength([string[]] $Items, [int] $Budget) {
    # Windows caps a command line at 32K characters; a real repository's file list overflows it.
    $batches = [System.Collections.Generic.List[object]]::new()
    $batch = [System.Collections.Generic.List[string]]::new(); $length = 0
    foreach ($t in $Items) {
        if ($batch.Count -gt 0 -and $length + $t.Length + 3 -gt $Budget) { $batches.Add($batch.ToArray()); $batch.Clear(); $length = 0 }
        $batch.Add($t); $length += $t.Length + 3
    }
    if ($batch.Count -gt 0) { $batches.Add($batch.ToArray()) }
    return $batches.ToArray()
}

function Test-GeneratedSourceFile {
    param([string] $TreePath, [string] $RelativePath, [Collections.Generic.Dictionary[string,bool]] $GeneratedCache)
    # Check current path metadata even on a cache hit: a descendant link must
    # never reach header reading or become a generated suffix exemption.
    try { $key = Resolve-SourceFilePath $TreePath $RelativePath }
    catch { return $false }
    if ($null -ne $GeneratedCache -and $GeneratedCache.ContainsKey($key)) { return $GeneratedCache[$key] }
    $generated = Read-GeneratedSourceFile $TreePath $RelativePath
    if ($null -ne $GeneratedCache) { $GeneratedCache[$key] = $generated }
    return $generated
}

function Read-GeneratedComment {
    param([IO.StreamReader] $Reader, [string] $Opening, [string] $Closing, [ref] $LinePrefix)
    # Retain only the start of each comment line. Collapse whitespace so even a
    # single enormous license line uses bounded memory without limiting headers.
    $prefix = [string]$LinePrefix.Value
    if ($prefix.Length -lt 128) { $prefix += $Opening }
    $tail = ''
    try {
        while (($value = $Reader.Read()) -ge 0) {
            $char = [char]$value
            if ($char -eq "`n" -or $char -eq "`r") {
                $prefix = ''
                if (-not $Closing) { return $false }
            }
            elseif ($prefix.Length -lt 128) {
                if ([char]::IsWhiteSpace($char)) {
                    if ($prefix -and -not $prefix.EndsWith(' ')) { $prefix += ' ' }
                }
                else { $prefix += $char }
                if ([regex]::IsMatch($prefix, '(?i)^\s*(?://+|\#|/\*+|\*|<!--|<#)?\s*<auto-generated(?:\s|/|>)')) { return $true }
            }
            if ($Closing) {
                $tail = ($tail + $char)
                if ($tail.EndsWith($Closing, [StringComparison]::Ordinal)) { return $false }
                if ($tail.Length -gt $Closing.Length) { $tail = $tail.Substring($tail.Length - $Closing.Length) }
            }
        }
        return $false
    }
    finally { $LinePrefix.Value = $prefix }
}

function Read-GeneratedSourceFile {
    param([string] $TreePath, [string] $RelativePath)
    try { $path = Resolve-SourceFilePath $TreePath $RelativePath }
    catch { return $false }
    $leaf = [IO.Path]::GetFileName($path)
    foreach ($glob in $script:GeneratedGlobs) { if ($leaf -like $glob) { return $true } }
    $reader = [IO.StreamReader]::new($path)
    try {
        # Stop at the first real token: markers in prose, literals or later
        # comments cannot classify a handwritten file. StreamReader strips BOMs.
        $linePrefix = ''
        while (($value = $reader.Read()) -ge 0) {
            $char = [char]$value
            if ([char]::IsWhiteSpace($char)) {
                if ($char -eq "`n" -or $char -eq "`r") { $linePrefix = '' }
                continue
            }
            $opening = ''; $closing = ''
            if ($char -eq '#') { $opening = '#' }
            elseif ($char -eq '/' -and $reader.Peek() -eq [int][char]'/') { $null = $reader.Read(); $opening = '//' }
            elseif ($char -eq '/' -and $reader.Peek() -eq [int][char]'*') { $null = $reader.Read(); $opening = '/*'; $closing = '*/' }
            elseif ($char -eq '<') {
                if ($reader.Peek() -eq [int][char]'#') { $null = $reader.Read(); $opening = '<#'; $closing = '#>' }
                else {
                    foreach ($expected in [char[]]'!--') { if ($reader.Read() -ne [int]$expected) { return $false } }
                    $opening = '<!--'; $closing = '-->'
                }
            }
            else { return $false }
            if (Read-GeneratedComment $reader $opening $closing ([ref]$linePrefix)) { return $true }
        }
        return $false
    }
    finally { $reader.Dispose() }
}

function Get-ScanFiles {
    [CmdletBinding()]
    param([Parameter(Mandatory)] [string] $TreePath, [string[]] $Pathspec, [switch] $IncludeGenerated,
        [Collections.Generic.Dictionary[string,bool]] $GeneratedCache)
    # Batched: pr-detect passes every file a PR touches, and ~1000 paths overflowed the
    # command line before git started. Exclude pathspecs go in every batch, or a batch
    # holding only includes would list the excluded files.
    $excludeMagic = '^:(!|\^|\([^)]*\bexclude\b)'
    $exclude = @($Pathspec | Where-Object { $_ -match $excludeMagic })
    $include = @($Pathspec | Where-Object { $_ -and $_ -notmatch $excludeMagic })
    $budget = 24000 - (($exclude | ForEach-Object { $_.Length + 3 } | Measure-Object -Sum).Sum)
    $batches = @(Split-ByLength $include $budget)
    if (-not $batches.Count) { $batches = @('') }
    $listed = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    $ok = $true
    foreach ($b in $batches) {
        # Includes are literal: a name that starts with ':' would otherwise parse as pathspec magic.
        $spec = @(@(@($b) | Where-Object { $_ } | ForEach-Object { ":(literal)$_" }) + $exclude)
        $gitArgs = @('-C', $TreePath, 'ls-files', '-z')
        if ($spec) { $gitArgs += @('--') + $spec }
        $consoleEncoding = [Console]::OutputEncoding
        try {
            [Console]::OutputEncoding = [Text.UTF8Encoding]::new($false)
            $raw = & git @gitArgs 2>$null
            $lsExit = $LASTEXITCODE
        }
        finally { [Console]::OutputEncoding = $consoleEncoding }
        if ($lsExit -ne 0) { $ok = $false; break }
        foreach ($f in (($raw -join '') -split "`0")) { if ($f) { [void]$listed.Add($f) } }
    }
    if ($ok) {
        $files = @($listed)
    }
    elseif (-not (Test-Path -LiteralPath (Join-Path $TreePath '.git'))) {
        # Not a git tree (contract-test fixtures): enumerate the filesystem instead.
        $rootFull = (Resolve-Path -LiteralPath $TreePath).Path
        $files = @(Get-ChildItem -LiteralPath $rootFull -Recurse -File | ForEach-Object { [IO.Path]::GetRelativePath($rootFull, $_.FullName).Replace('\', '/') })
    }
    else { throw "git ls-files failed in $TreePath" }
    return @($files | Where-Object {
        $rel = $_
        $segments = $rel -split '/'
        if ($segments | Where-Object { $_ -in $script:ExcludeDirs }) { return $false }
        $leaf = $segments[-1]
        foreach ($g in $script:ExcludeGlobs) { if ($leaf -like $g) { return $false } }
        try { $null = Resolve-SourceFilePath $TreePath $rel }
        catch { return $false }
        if (-not $IncludeGenerated -and (Test-GeneratedSourceFile $TreePath $rel $GeneratedCache)) { return $false }
        return $true
    } | Sort-Object)
}

function Get-SmellIdFromCheck([string] $CheckId) {
    $leaf = ($CheckId -split '\.')[-1]
    return ($leaf -split '-')[0]
}

function Test-ToolAvailable([string[]] $Command) {
    if (-not $Command -or $Command.Count -eq 0) { return $false }
    return [bool](Get-Command $Command[0] -ErrorAction SilentlyContinue)
}

function Get-SemgrepRuleFiles([string] $SkillRoot, [string] $RulePath) {
    # A catalogue smell names ONE rule file, but some smells (e.g. S13) have language
    # siblings named '<id>-*.yml' in the same directory (e.g. S13-ts.yml). Pass semgrep
    # the named rule plus every sibling so a catalogue naming only detectors/rules/S13.yml
    # still fires the TS/JS variant.
    $full = Join-Path $SkillRoot $RulePath
    $dir = Split-Path -Parent $full
    $base = [IO.Path]::GetFileNameWithoutExtension($full)
    $siblings = @(Get-ChildItem -LiteralPath $dir -Filter "$base-*.yml" -File -ErrorAction SilentlyContinue | Select-Object -ExpandProperty FullName)
    return @($full) + $siblings
}

function Get-CatchSpans([string] $Text, [int] $StartLine, [string] $Language) {
    # Keep offsets and newlines while removing comments and string literals from scope matching.
    $literals = '(?s)"{3}.*?"{3}|''{3}.*?''{3}|@"(?:""|[^"])*"|"(?:\\.|[^"\\])*"|''(?:\\.|[^''\\])*''|`(?:\\.|[^`\\])*`'
    $literals += if ($Language -eq 'python') { '|\#[^\r\n]*' } else { '|/\*.*?\*/|//[^\r\n]*' }
    $code = [regex]::Replace($Text, $literals, [Text.RegularExpressions.MatchEvaluator]{ param($m) $m.Value -replace '[^\r\n]', ' ' })
    if ($Language -eq 'python') {
        $lines = @($code -split "`r?`n")
        for ($i = 0; $i -lt $lines.Count; $i++) {
            if ($lines[$i] -notmatch '^(\s*)except\b') { continue }
            $indent = $Matches[1].Length
            $header = $i; $depth = 0; $tail = $null
            for (; $header -lt $lines.Count; $header++) {
                for ($column = 0; $column -lt $lines[$header].Length; $column++) {
                    $char = $lines[$header][$column]
                    if ($char -in '(', '[', '{') { $depth++ }
                    if ($char -in ')', ']', '}') { $depth-- }
                    if ($char -eq ':' -and $depth -eq 0) { $tail = $lines[$header].Substring($column + 1).Trim(); break }
                }
                if ($null -ne $tail) { break }
            }
            if ($null -eq $tail) { continue }
            if ($tail -eq 'pass') { [pscustomobject]@{ Start = $StartLine + $i; End = $StartLine + $header; Column = $indent + 1 }; continue }
            $end = $header
            for ($j = $header + 1; $j -lt $lines.Count; $j++) {
                if (-not $lines[$j].Trim()) { continue }
                if (($lines[$j].Length - $lines[$j].TrimStart().Length) -le $indent) { break }
                $end = $j
            }
            $body = if ($end -gt $header) { ($lines[($header + 1)..$end] -join "`n").Trim() } else { '' }
            if ($body -eq 'pass') { [pscustomobject]@{ Start = $StartLine + $i; End = $StartLine + $end; Column = $indent + 1 } }
        }
        return
    }
    foreach ($match in [regex]::Matches($code, '\bcatch\b[^{}]*\{')) {
        $open = $match.Index + $match.Length - 1
        $depth = 1; $close = $open + 1
        while ($close -lt $code.Length -and $depth -gt 0) {
            if ($code[$close] -eq '{') { $depth++ }
            if ($code[$close] -eq '}') { $depth-- }
            $close++
        }
        if ($depth -eq 0 -and -not $code.Substring($open + 1, $close - $open - 2).Trim()) {
            [pscustomobject]@{ Start = $StartLine + ([regex]::Matches($code.Substring(0, $match.Index), "`n")).Count; End = $StartLine + ([regex]::Matches($code.Substring(0, $close - 1), "`n")).Count; Column = $match.Index - $code.LastIndexOf([char]10, $match.Index) }
        }
    }
}

function Resolve-SourceFilePath {
    param([string] $TreePath, [string] $Name)
    $treeFull = [IO.Path]::GetFullPath($TreePath)
    $full = [IO.Path]::GetFullPath($Name, $treeFull)
    $relative = [IO.Path]::GetRelativePath($treeFull, $full).Replace('\', '/')
    if ($relative -eq '..' -or $relative.StartsWith('../', [StringComparison]::Ordinal) -or [IO.Path]::IsPathRooted($relative)) {
        throw 'source path is outside the scanned tree'
    }
    # Inspect each descendant before entering the next component, so neither
    # header classification nor report validation follows a directory link.
    # The explicitly chosen tree root itself may be a junction or symlink.
    $current = $treeFull
    foreach ($segment in ($relative -split '/')) {
        $current = Join-Path $current $segment
        $item = Get-Item -LiteralPath $current -Force -ErrorAction Stop
        if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) { throw 'source path contains a descendant link' }
    }
    if ($item -isnot [IO.FileInfo]) { throw 'source path is not a file' }
    return $full
}

function Resolve-CloneReportPath {
    param([string] $TreePath, [string] $Name)
    $full = Resolve-SourceFilePath $TreePath $Name
    # Probe read access without reading content. Validate every partner before
    # accepting any report entries, even when classification is already cached.
    $stream = [IO.File]::Open($full, [IO.FileMode]::Open, [IO.FileAccess]::Read, ([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete))
    $stream.Dispose()
    return [IO.Path]::GetRelativePath([IO.Path]::GetFullPath($TreePath), $full).Replace('\', '/')
}

function Invoke-SmellDetectors {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)] [string] $TreePath,
        [Parameter(Mandatory)] $Catalogue,
        [Parameter(Mandatory)] [string] $SkillRoot,
        [Parameter(Mandatory)] [string] $OutDir,
        [string[]] $Pathspec,
        [string] $SemgrepCommand = 'semgrep',
        [AllowEmptyCollection()] [string[]] $JscpdCommand = @('npx', '--yes', 'jscpd@4.0.5'),
        [string] $PythonCommand = (@('python3', 'python') | Where-Object { Get-Command $_ -ErrorAction SilentlyContinue } | Select-Object -First 1),
        # Tree-relative globs jscpd must ignore. jscpd scans the whole tree, not $files, so a
        # caller that excludes paths (pr-detect -Exclude) has to say so here too.
        [string[]] $JscpdExclude = @()
    )
    New-Item -ItemType Directory -Force -Path $OutDir | Out-Null
    $OutDir = (Resolve-Path -LiteralPath $OutDir).Path
    $TreePath = (Resolve-Path -LiteralPath $TreePath).Path
    # Explicit invocation scope: reusable dot-sourced helpers and a later scan of
    # the same tree must observe edits. Ordinal keys preserve Linux case distinctions.
    $generatedCache = [Collections.Generic.Dictionary[string,bool]]::new([StringComparer]::Ordinal)
    $files = @(Get-ScanFiles -TreePath $TreePath -Pathspec $Pathspec -GeneratedCache $generatedCache)
    $raw = [System.Collections.Generic.List[object]]::new()
    $coverage = [System.Collections.Generic.List[object]]::new()
    $tools = @{}

    $present = @($files | ForEach-Object { $script:LanguageByExtension[[IO.Path]::GetExtension($_).ToLowerInvariant()] } | Where-Object { $_ } | Sort-Object -Unique)
    $smells = @($Catalogue.Smells)

    # --- semgrep: every regex + semgrep rule in ONE pass ---------------------------
    $semgrepSmells = @($smells | Where-Object { $_.detector.kind -in 'regex', 'semgrep' })
    if ($semgrepSmells.Count -gt 0) {
        if (-not (Get-Command $SemgrepCommand -ErrorAction SilentlyContinue)) {
            throw "semgrep ('$SemgrepCommand') is required and was not found. Install it (pip install semgrep) - regex and AST smells cannot be assessed without it."
        }
        $tools['semgrep'] = ((& $SemgrepCommand --version --disable-version-check) | Select-Object -First 1).Trim()
        $configArgs = @($semgrepSmells | ForEach-Object { $sid = $_.id; Get-SemgrepRuleFiles -SkillRoot $SkillRoot -RulePath $_.detector.rule } | ForEach-Object { '--config'; $_ })
        $targets = @($files | ForEach-Object { Join-Path $TreePath $_ })
        # Explicit targets, not the tree root: a directory scan would apply semgrep's own
        # default ignores (tests/, among others) and diverge from Get-ScanFiles. Batched
        # because one invocation over a real repository overflows the Windows 32K
        # command line ("The filename or extension is too long" on a large repository).
        $budget = 24000 - (($configArgs | ForEach-Object { $_.Length + 3 } | Measure-Object -Sum).Sum)
        # A semgrep run that did not finish cleanly proves nothing about the files it was
        # given: a non-zero exit, unparseable output, an `errors` entry, or a path it skipped
        # because analysis failed are all coverage gaps, never a clean 'assessed'.
        $semgrepFailure = [System.Collections.Generic.List[string]]::new()
        $skippedRel = [System.Collections.Generic.List[string]]::new()
        $fileFailure = @{}
        $catchSeen = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        foreach ($b in @(Split-ByLength $targets $budget)) {
            $json = & $SemgrepCommand scan @configArgs --json --metrics=off --verbose --no-git-ignore --disable-version-check @b 2>$null | Out-String
            $semgrepExit = $LASTEXITCODE
            $parsed = $null
            try { $parsed = ConvertFrom-Json $json -ErrorAction Stop } catch { $parsed = $null }
            if ($semgrepExit -ne 0) { $semgrepFailure.Add("semgrep exited $semgrepExit") }
            if ($null -eq $parsed) { if ($semgrepExit -eq 0) { $semgrepFailure.Add('semgrep wrote no parseable JSON') }; continue }
            $errs = @($parsed.errors | Where-Object { $_ })
            foreach ($err in $errs) {
                $message = "semgrep error: $((([string]$err.message).Trim() -split "`n")[0])"
                $paths = @(@($err.path) + @($err.spans | ForEach-Object { $_.file }) | Where-Object { $_ } | Select-Object -Unique)
                if (-not $paths.Count) { $semgrepFailure.Add($message); continue }
                foreach ($path in $paths) {
                    $relPath = if ([IO.Path]::IsPathRooted($path)) { [IO.Path]::GetRelativePath($TreePath, $path) } else { $path }
                    $relPath = $relPath.Replace('\', '/')
                    $fileFailure[$relPath] = $message
                    $skippedRel.Add($relPath)
                }
            }
            foreach ($sk in @($parsed.paths.skipped | Where-Object { $_ })) {
                if ($sk -and [string]$sk.reason -match 'error|fail|size|time|big|insufficient_permissions') {
                    $path = [string]$sk.path
                    $relPath = if ([IO.Path]::IsPathRooted($path)) { [IO.Path]::GetRelativePath($TreePath, $path) } else { $path }
                    $skippedRel.Add($relPath.Replace('\', '/'))
                }
            }
            foreach ($r in @($parsed.results | Where-Object { $_ })) {
                $rel = [IO.Path]::GetRelativePath($TreePath, $r.path).Replace('\', '/')
                $text = ([string]$r.extra.lines).Trim()
                $end = if ($r.end.line) { [int]$r.end.line } else { [int]$r.start.line }
                # Logged-out semgrep masks the matched lines as "requires login"; read them from the file.
                if ($text -eq 'requires login') {
                    $text = (([IO.File]::ReadAllLines($r.path))[([int]$r.start.line - 1)..($end - 1)] -join "`n").Trim()
                }
                $smellId = Get-SmellIdFromCheck $r.check_id
                if ($smellId -eq 'S13') {
                    $language = $script:LanguageByExtension[[IO.Path]::GetExtension($rel).ToLowerInvariant()]
                    # Use source lines without trimming so nested matches share absolute clause columns.
                    $clauseText = ([IO.File]::ReadAllLines($r.path))[([int]$r.start.line - 1)..($end - 1)] -join "`n"
                    $spans = @(Get-CatchSpans $clauseText ([int]$r.start.line) $language)
                    if (-not $spans.Count) {
                        $fileFailure[$rel] = 'could not scope semgrep S13 clause'
                        $skippedRel.Add($rel)
                    }
                    foreach ($span in $spans) {
                        if (-not $catchSeen.Add("$rel|$($span.Start)|$($span.Column)|$($span.End)")) { continue }
                        $raw.Add([pscustomobject]@{ smell = $smellId; file = $rel; line = [int]$r.start.line; endLine = $span.End; scopeStart = $span.Start; text = $text; detector = "semgrep@$($tools['semgrep'])" })
                    }
                    continue
                }
                $raw.Add([pscustomobject]@{ smell = $smellId; file = $rel; line = [int]$r.start.line; endLine = $end; scopeStart = [int]$r.start.line; text = $text; detector = "semgrep@$($tools['semgrep'])" })
            }
        }
        $failureText = ($semgrepFailure | Select-Object -Unique) -join '; '
        foreach ($s in $semgrepSmells) {
            $langs = @($s.languages)
            if ($failureText) {
                # The run cannot be attributed to a language: every semgrep smell is a gap.
                if ($files.Count) { $coverage.Add([pscustomobject]@{ smell = $s.id; status = 'not assessed'; reason = $failureText }) }
                continue
            }
            # No files scanned means nothing assessed: add no entry, as for a language that is not present.
            if ($langs -contains 'any') {
                if ($files.Count) {
                    if ($skippedRel.Count) { $coverage.Add([pscustomobject]@{ smell = $s.id; status = 'not assessed'; reason = "semgrep skipped $($skippedRel.Count) path(s): $(($skippedRel | Select-Object -First 3) -join ', ')" }) }
                    else { $coverage.Add([pscustomobject]@{ smell = $s.id; status = 'assessed'; reason = '' }) }
                }
                continue
            }
            foreach ($l in $present) {
                if ($s.id -eq 'S13' -and $l -eq 'powershell') { continue } # Assessed by the PowerShell parser below.
                if ($langs -contains $l) {
                    $gap = @($skippedRel | Where-Object { $script:LanguageByExtension[[IO.Path]::GetExtension($_).ToLowerInvariant()] -eq $l })
                    if ($gap.Count) {
                        $notes = @($gap | ForEach-Object { $fileFailure[$_] } | Where-Object { $_ } | Select-Object -Unique) -join '; '
                        $coverage.Add([pscustomobject]@{ smell = $s.id; status = 'not assessed'; reason = "semgrep skipped $($gap.Count) $l path(s): $(($gap | Select-Object -First 3) -join ', ') $notes" })
                    }
                    else { $coverage.Add([pscustomobject]@{ smell = $s.id; status = 'assessed'; reason = $l }) }
                }
                else { $coverage.Add([pscustomobject]@{ smell = $s.id; status = 'not assessed'; reason = "no rule for $l" }) }
            }
        }
    }

    # Semgrep has no PowerShell AST. Parse catch bodies with the runtime's parser.
    if (@($semgrepSmells | Where-Object id -eq 'S13').Count -and $present -contains 'powershell') {
        $parseFailures = [System.Collections.Generic.List[string]]::new()
        foreach ($rel in @($files | Where-Object { [IO.Path]::GetExtension($_).ToLowerInvariant() -in '.ps1', '.psm1' })) {
            $tokens = $null; $parseErrors = $null
            try { $ast = [System.Management.Automation.Language.Parser]::ParseFile((Join-Path $TreePath $rel), [ref]$tokens, [ref]$parseErrors) }
            catch { $parseFailures.Add($rel); continue }
            if ($parseErrors.Count) { $parseFailures.Add($rel); continue }
            foreach ($clause in @($ast.FindAll({ param($node) $node -is [System.Management.Automation.Language.CatchClauseAst] }, $true))) {
                if ($clause.Body.Statements.Count -or $clause.Body.Traps.Count) { continue }
                $raw.Add([pscustomobject]@{ smell = 'S13'; file = $rel; line = $clause.Extent.StartLineNumber; endLine = $clause.Extent.EndLineNumber; scopeStart = $clause.Extent.StartLineNumber; text = $clause.Extent.Text.Trim(); detector = "powershell-parser@$($PSVersionTable.PSVersion)" })
            }
        }
        $tools['powershell-parser'] = [string]$PSVersionTable.PSVersion
        $coverage.Add([pscustomobject]@{ smell = 'S13'; status = $(if ($parseFailures.Count) { 'not assessed' } else { 'assessed' }); reason = $(if ($parseFailures.Count) { "powershell parse failed: $($parseFailures -join ', ')" } else { 'powershell' }) })
    }

    # --- jscpd: clone smells --------------------------------------------------------
    foreach ($s in @($smells | Where-Object { $_.detector.kind -eq 'clone' })) {
        if (-not (Test-ToolAvailable $JscpdCommand)) {
            $coverage.Add([pscustomobject]@{ smell = $s.id; status = 'not assessed'; reason = 'jscpd unavailable' }); continue
        }
        # A fresh child isolates retries from old reports without deleting caller output.
        $report = Join-Path $OutDir ('jscpd/' + [guid]::NewGuid().ToString('N'))
        $ignoreDirs = $script:ExcludeDirs + @('.git', '.vs', '.firecrawl', 'TestResults')
        # Run discovery from the tree with a relative input pattern. An absolute
        # tree containing glob metacharacters would be interpreted by fast-glob;
        # relative ignores also cannot match the tree's own worktree ancestors.
        # jscpd scans outside the PR pathspec and uses case-sensitive globs on Linux.
        # Exact discovered names cover both suffix casing and header-only snapshots.
        $generated = @(Get-ScanFiles -TreePath $TreePath -IncludeGenerated | Where-Object { Test-GeneratedSourceFile $TreePath $_ $generatedCache })
        # Only discovered literal names are escaped; caller and suffix patterns
        # remain globs. Preserve exact casing for Linux generated-file exclusions.
        $generatedIgnore = @($generated | ForEach-Object { [regex]::Replace($_, '([*?\[\]{}()!+@|])', '\$1') })
        $ignore = @(@($ignoreDirs | ForEach-Object { "**/$_/**" }) + @($script:ExcludeGlobs | ForEach-Object { "**/$_" }) + @($script:GeneratedGlobs | ForEach-Object { "**/$_" }) + $generatedIgnore + @('**/docs/sources/**', '**/.claude/worktrees/**') + @($JscpdExclude | Where-Object { $_ } | ForEach-Object { $_.TrimStart('/') -replace '^\./', '' }))
        # npm's Windows command shim cannot carry an estate-sized ignore list.
        $configPath = Join-Path $OutDir 'jscpd-options.json'
        [IO.File]::WriteAllText($configPath, (@{ ignore = $ignore } | ConvertTo-Json -Depth 3), [Text.UTF8Encoding]::new($false))
        $formats = ($script:LanguageByExtension.Values | Sort-Object -Unique) -join ','
        # Resolve the prefix executable before changing location; remaining file
        # arguments must already be absolute. --absolute keeps report names absolute.
        $jscpdFailure = ''
        try {
            $jscpdExecutable = Get-Command $JscpdCommand[0] -ErrorAction Stop
            Push-Location -LiteralPath $TreePath
            try {
                & $jscpdExecutable @($JscpdCommand | Select-Object -Skip 1) --config ($configPath.Replace('\', '/')) --silent --absolute --noSymlinks --reporters json --output ($report.Replace('\', '/')) --min-lines 8 --max-lines 10000 --max-size 1mb --format $formats '.' 2>$null | Out-Null
                $jscpdExit = $LASTEXITCODE
            }
            finally { Pop-Location }
        }
        catch { $jscpdFailure = "jscpd failed: $($_.Exception.Message)" }
        if ($jscpdFailure) {
            $coverage.Add([pscustomobject]@{ smell = $s.id; status = 'not assessed'; reason = $jscpdFailure }); continue
        }
        if ($jscpdExit -ne 0) {
            $coverage.Add([pscustomobject]@{ smell = $s.id; status = 'not assessed'; reason = "jscpd exited $jscpdExit" }); continue
        }
        $jsonPath = Join-Path $report 'jscpd-report.json'
        if (-not (Test-Path -LiteralPath $jsonPath)) {
            $coverage.Add([pscustomobject]@{ smell = $s.id; status = 'not assessed'; reason = "jscpd ran but wrote no report (exit $jscpdExit)" }); continue
        }
        try {
            $normalizedClones = [Collections.Generic.List[object]]::new()
            $parsed = Get-Content -LiteralPath $jsonPath -Raw | ConvertFrom-Json -ErrorAction Stop
            if ($null -eq $parsed -or $parsed.duplicates -isnot [array]) { throw 'missing duplicates array' }
            foreach ($d in $parsed.duplicates) {
                if (-not $d.firstFile.name -or -not $d.secondFile.name -or
                    [int]$d.firstFile.start -lt 1 -or [int]$d.secondFile.start -lt 1 -or [int]$d.lines -lt 1 -or
                    ($null -ne $d.firstFile.end -and [int]$d.firstFile.end -lt [int]$d.firstFile.start) -or
                    ($null -ne $d.secondFile.end -and [int]$d.secondFile.end -lt [int]$d.secondFile.start)) { throw 'invalid duplicate entry' }
                # Invalid filename strings (including embedded NUL) must be a
                # coverage gap too. Validate both paths before accepting any hits.
                $first = Resolve-CloneReportPath $TreePath $d.firstFile.name
                $second = Resolve-CloneReportPath $TreePath $d.secondFile.name
                $normalizedClones.Add([pscustomobject]@{ Duplicate = $d; First = $first; Second = $second })
            }
        }
        catch {
            $coverage.Add([pscustomobject]@{ smell = $s.id; status = 'not assessed'; reason = "jscpd wrote an invalid report: $($_.Exception.Message)" }); continue
        }
        $tools['jscpd'] = $JscpdCommand[-1]
        foreach ($clone in $normalizedClones) {
            $d = $clone.Duplicate
            if ($d.firstFile.name -eq $d.secondFile.name) { continue } # S14 is cross-file duplication.
            $first = $clone.First
            $second = $clone.Second
            if ((Test-GeneratedSourceFile $TreePath $first $generatedCache) -or (Test-GeneratedSourceFile $TreePath $second $generatedCache)) { continue }
            $firstEnd = if ($d.firstFile.end) { [int]$d.firstFile.end } else { [int]$d.firstFile.start + [int]$d.lines - 1 }
            $raw.Add([pscustomobject]@{ smell = $s.id; file = $first; line = [int]$d.firstFile.start; endLine = $firstEnd; scopeStart = [int]$d.firstFile.start; text ="duplicates ${second}:$($d.secondFile.start) ($($d.lines) lines)"; detector = "jscpd@$($tools['jscpd'])" })
        }
        $coverage.Add([pscustomobject]@{ smell = $s.id; status = 'assessed'; reason = '' })
    }

    # --- scripts ----------------------------------------------------------------------
    foreach ($s in @($smells | Where-Object { $_.detector.kind -eq 'script' })) {
        $scriptPath = Join-Path $SkillRoot $s.detector.rule
        if (-not $PythonCommand) { $coverage.Add([pscustomobject]@{ smell = $s.id; status = 'not assessed'; reason = 'python unavailable' }); continue }
        $listPath = Join-Path $OutDir "files-$($s.id).txt"
        Set-Content -LiteralPath $listPath -Value $files -Encoding utf8NoBOM
        # stderr goes to its own file, never into stdout: a Python SyntaxWarning (ast.parse on a
        # source file with an invalid escape sequence) would otherwise land inside the JSON.
        $errPath = Join-Path $OutDir "stderr-$($s.id).txt"
        $out = & $PythonCommand $scriptPath --root $TreePath --files $listPath --smell $s.id 2>$errPath | Out-String
        $scriptExit = $LASTEXITCODE
        $err = if (Test-Path -LiteralPath $errPath) { (Get-Content -LiteralPath $errPath -Raw) } else { '' }
        if ($scriptExit -ne 0) {
            $detail = if ($err -and $err.Trim()) { $err } else { $out }
            $coverage.Add([pscustomobject]@{ smell = $s.id; status = 'not assessed'; reason = "script exited ${scriptExit}: $($detail.Trim() -split "`n" | Select-Object -Last 1)" }); continue
        }
        try { $result = $out | ConvertFrom-Json -ErrorAction Stop }
        catch { $coverage.Add([pscustomobject]@{ smell = $s.id; status = 'not assessed'; reason = "script wrote no parseable JSON: $($out.Trim() -split "`n" | Select-Object -First 1)" }); continue }
        foreach ($h in @($result.hits)) {
            $hitEnd = if ($h.endLine) { [int]$h.endLine } else { [int]$h.line }
            $raw.Add([pscustomobject]@{ smell = $s.id; file = $h.file; line = [int]$h.line; endLine = $hitEnd; scopeStart = [int]$h.line; text = [string]$h.text; detector = "script:$(Split-Path -Leaf $scriptPath)" })
        }
        $coverage.Add([pscustomobject]@{ smell = $s.id; status = $result.status; reason = [string]$result.reason })
    }

    foreach ($s in @($smells | Where-Object { $_.detector.kind -eq 'judgment' })) {
        $coverage.Add([pscustomobject]@{ smell = $s.id; status = 'judgment'; reason = '' })
    }

    $sorted = @($raw | Sort-Object smell, file, line, text)
    $i = 0
    $hits = @(foreach ($h in $sorted) { $i++; [pscustomobject][ordered]@{ id = ('h{0:D4}' -f $i); smell = $h.smell; file = $h.file; line = $h.line; endLine = $h.endLine; scopeStart = $h.scopeStart; text = $h.text; detector = $h.detector } })
    $lines = @($hits | ForEach-Object { $_ | ConvertTo-Json -Compress -Depth 3 })
    [IO.File]::WriteAllText((Join-Path $OutDir 'hits.jsonl'), (($lines -join "`n") + $(if ($lines) { "`n" } else { '' })))
    $coverage | ConvertTo-Json -Depth 3 -AsArray | Set-Content -LiteralPath (Join-Path $OutDir 'coverage.json') -Encoding utf8NoBOM

    return [pscustomobject]@{ Hits = $hits; Coverage = @($coverage); Tools = $tools }
}
